// 冻结基线正文与可追加阶段证据分离，避免正常留痕改变风格指纹。
templates.core["visual-baseline.md"] = "# 冻结全局视觉基线\n\n本文件只保存当前冻结版本的全局视觉规则，不追加 V2/V3/V4/V5 证据。冻结后按完整文件字节计算 SHA-256；规则变化必须生成新版本和新哈希，并使受影响证据失效。静态基线状态只能写 `global-static-baseline-frozen`，不能写裸 `frozen`，也不能声称 V2。\n\n## 基线身份\n\n- 基线 ID：\n- 版本：\n- 状态：draft\n- 冻结日期：\n- 负责人：\n- 机器验证器版本与运行标识：\n\n## 冻结规则\n\n| 系统 | 不变量 | 允许变量 | 禁止项 |\n| --- | --- | --- | --- |\n";
templates.core["visual-design.md"] = templates.core["visual-design.md"]
  .replace("本文件是全局视觉控制的单一事实源。V1 建立候选，V2a 冻结；冻结后不得静默改写。", "本文件是可追加的视觉方向、阶段证据与冻结基线索引；全局基线在 G0/V0 完成三候选人工选择后冻结，不可变规则正文位于 docs/visual-baseline.md。")
  .replace("风格指纹不回填本文件。冻结后对本文件完整字节计算 SHA-256，并仅在 `visual-assets.json` 记录 `sha256:<64 位小写十六进制>`；正式文件检查会重新计算并拒绝静默修改。", "风格指纹只计算 docs/visual-baseline.md 完整字节；本文件追加 V2/V3/V4/V5 留痕不会改变基线哈希。");
templates.core["visual-design.md"] = templates.core["visual-design.md"].replace("状态 draft/frozen", "状态 draft/global-static-baseline-frozen");
templates.core["visual-design.md"] += "\n## 冻结基线索引与阶段证据\n\n冻结规则正文位于 `docs/visual-baseline.md`，其 SHA-256 写入 `visual-assets.json`。本文件仅追加方向探索、V2/V3/V4/V5 证据和基线版本索引，不得把阶段留痕写回已哈希基线正文。\n";
// 生成模板同步透明生产合同；生成式透明素材固定先校验不透明纯色背景，再执行公共去背景。
templates.core["visual-design.md"] = templates.core["visual-design.md"].replace("非空 `postprocess` 列表", "字符串 `postprocess` 数组（可为空）");
templates.core["visual-design.md"] += "\n生成式 alpha 资产必须先生成整张不透明的单一指定 HEX 纯色背景 PNG，再执行公共背景处理。实际提示词不得请求透明 PNG/Alpha，不得接受棋盘格或网格预览；记录 `transparency_strategy=background-removal`、`source_background_mode=opaque`、显式 `source_background_color`、实际 `generator`/`generator_version`（未暴露时写 `not-provided`）、源/输出路径、Alpha、完成时间和 evidence，且背景颜色必须与脚本参数一致。使用 `remove-background-local.mjs --require-solid-background` 校验源图，失败必须重新生成或修正输入；`background_removal_attempts` 只追加 `report.background_removal_attempt`，不嵌入完整报告，失败必须记录原因并保留历史，重试次数由任务配置设定上限；不因重试自动新增外部调用授权。已有真实透明图按既有资源复用，不伪造生成去背记录；alpha=false 的完整场景背景不受纯色要求约束。\n";
templates.core["visual-design.md"] += "\n所有生成式位图单图顺序固定为：生成原图 →（alpha=true 时）校验不透明纯色背景 → 公共脚本去背景 → Sharp 尺寸归一化 → V3/final/runtime。首次输出比例不符时最多重生一次；第二次仍不符时，若冻结焦点和安全事实允许，使用 `normalization_record.operation=crop-and-resize-to-contract`，记录两次真实原始生成 attempt、SHA、尺寸、focus 和最大目标比例 `crop_rect`；若裁切会损伤主体、文字、透明轮廓或关键构图，则先对原图生成式延展到目标比例，再重新校验纯色背景并执行背景处理和普通归一化。该分流适用于所有生成式位图，`normalization_record.source_file` 绑定当前输入（透明路线绑定背景处理输出），`padding_policy=none`；禁止非等比拉伸、padding、contain、复制边缘或裁切冻结 `reference_target`；尺寸正确也写 `normalization_record.operation=not-required`，透明 PNG 前后保留 Alpha。\n";

// 所有生成式效果图都从同一份静态全局基线和全部锚点取样；该规则不把项目具体美术风格硬编码进模板。
templates.core["visual-baseline.md"] += "\n## 三候选生成与人工冻结硬门\n\n全局基线 brief 建立后，必须在相同 brief、视口、参考输入和生成条件下生成恰好三张候选效果图，并将三张图同屏交给人工比较。候选阶段不能把状态写成 `global-static-baseline-frozen`；在人工确认前，基线正文和 `globalVisualBaselineSelection` 均保持 `draft`/`PENDING`。\n\n### 基线 brief\n\n- brief ID：\n- brief 文件：\n- brief SHA-256：\n- generation batch ID：\n- conditions fingerprint：\n\n### 三张候选效果图\n\n| candidateId | origin | status | 图片路径/SHA-256 | generation record 路径/SHA-256 | 同屏呈现证据 |\n| --- | --- | --- | --- | --- | --- |\n| A | generated | GENERATED |  |  |  |\n| B | generated | GENERATED |  |  |  |\n| C | generated | GENERATED |  |  |  |\n\n候选 ID 必须唯一；每张图必须绑定实际图片文件和生成记录文件的 SHA-256，三条生成记录必须绑定同一 Work Item、brief、generation batch 与 conditions fingerprint。缺少、重复、非 generated、SHA 漂移或候选数量不是 3 张均不得冻结。\n\n### 唯一人工选择确认\n\n| reviewMode | status | selectedCandidateId | presentedCandidateIds（必须为 A/B/C） | 决定记录文件/SHA-256 | 确认时间 | 用户原文 |\n| --- | --- | --- | --- | --- | --- | --- |\n| SINGLE_HUMAN | PENDING |  | A, B, C |  |  |  |\n\n只有人工选择记录为唯一 `SINGLE_HUMAN` 且 `CONFIRMED`，并绑定决定文件、确认时间和用户原文后，才能把 `baseline.status`、Work Item `globalStaticBaselineState` 和 `visualStageState` 写成 `global-static-baseline-frozen`。`AUTO`、`pending`、说明文字或全局状态字段都不能代替人工选择。\n\n### 正式冻结身份\n\n- baseline ID / version：\n- document：`docs/visual-baseline.md`\n- documentSha256 / styleFingerprint（必须等于正文真实 SHA-256）：\n- primaryAnchor（必须绑定 selectedCandidate）：\n- selectedCandidateId / 图片路径 / SHA-256：\n- globalVisualBaselineSelectionRef（path + sha256 + 可选 workItemId）：\n\n正式冻结后正文不可静默改写；任何 brief、候选、决定、正文或锚点 SHA 漂移都必须使冻结引用失效并重新生成三候选、重新进行人工选择。\n\n## 生成一致性硬门\n\n生成场景主效果图、宿主场景上下文效果图以及 effect-image 原子资产前，必须先完成上述三候选人工冻结流程，再引用 `visual_baseline`：`status=global-static-baseline-frozen`、`document=docs/visual-baseline.md`、`id`、`version`、`style_fingerprint` 和完整 `anchor_evidence`。生成记录必须使用 `origin=generated`，逐项记录 `visual_baseline_id`、`visual_baseline_version`、`style_fingerprint`、`baseline_document`、全部 `style_reference_inputs`（路径与 SHA）、canonical 全局一致性提示词、`style_drift_policy=forbid`、实际 `full_prompt`、`prompt_sent=true`、`target_sha256`、`output_sha256`、`consistency_status=passed` 和 `consistency_evidence`（路径与 SHA）。外部或用户提供的效果图使用 `origin=provided`，禁止补写伪生成记录。全局基线是生成强制输入，但不冒充 V2；V2 仍负责方向冻结。\n\n固定全局一致性提示词：保持当前项目全局视觉语言、颜色材质、光照、线条、装饰密度、UI形状与全局视觉锚点一致，禁止风格迁移、重设计、跨项目风格混用。\n";
// 选择引用只写入可追加索引，冻结正文禁止写入 selectionRef 或其 SHA，避免正文与选择证据循环绑定。
templates.core["visual-baseline.md"] = templates.core["visual-baseline.md"]
  .replace("三条生成记录必须绑定同一 Work Item", "三条生成记录必须绑定同一生产者 Work Item")
  .replace("在人工确认前，基线正文和 `globalVisualBaselineSelection` 均保持 `draft`/`PENDING`。", "在人工确认前，独立选择证据文件与基线正文均保持 `draft`/`PENDING`。")
  .replace("- globalVisualBaselineSelectionRef（path + sha256 + 可选 workItemId）：", "- 选择证据引用仅写入 Work Item、visual-assets.json、visual-design.md；冻结正文禁止写入引用或引用 SHA：");
templates.optional.assets["visual-assets.json"] = templates.optional.assets["visual-assets.json"].replace('"anchor_evidence": []', '"anchor_evidence": [{ "path": "evidence/visual/global-anchor.png", "sha256": null }]');
templates.core["visual-design.md"] += "\n## 全局基线三候选人工选择证据\n\n全局视觉方向先写入 brief，再生成恰好三张同条件候选效果图。三张候选必须同屏呈现给人工，人工只能从三张中选择一张并以 `SINGLE_HUMAN`/`CONFIRMED` 记录决定文件、决定 SHA、确认时间和用户原文；确认前状态只能为 `draft`/`PENDING`，不得声称 `global-static-baseline-frozen`。机器引用统一使用 `globalVisualBaselineSelectionRef`（path + sha256 + 可选 workItemId），对应 `global-visual-baseline-selection/1.0` 文件，且该文件还要绑定 brief、三张 generated 图片及 generation record、冻结正文真实 SHA、primaryAnchor 和 selectedCandidate。全局基线人工选择是单独硬门，不能替代每个场景 V2 的拆解图确认。\n\n| selectionId | Work Item | brief/path/SHA | 三候选图片与生成记录 | 人工 reviewMode/status | selectedCandidateId | 决定文件/SHA | baseline status |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n";
templates.core["visual-design.md"] = templates.core["visual-design.md"]
  .replace("机器引用统一使用 `globalVisualBaselineSelectionRef`（path + sha256 + 可选 workItemId）", "机器引用统一使用 `globalVisualBaselineSelectionRef`（path + sha256；可选 workItemId 仅表示生产者 Work Item）")
  .replace("| selectionId | Work Item |", "| selectionId | 生产者 Work Item |")
  .replace("对应 `global-visual-baseline-selection/1.0` 文件", "对应独立 `global-visual-baseline-selection.json` 根文件（schema `threejs-global-visual-baseline-selection/1.0`）");
templates.core["visual-design.md"] += "\n项目固定序列：建立全局基线 brief → 生成三张同条件候选效果图 → 同屏交给人工 → 人工选择确认一张 → 正式冻结全局基线 → foundation-only 项目骨架/基础模块 → 逐场景 V1 生成或接收 scene master/reference target、宿主上下文和初步还原草案 → V2 拆解确认与生产方案 → V3 正式资源验收 → V4 页面还原草图保存与人工确认 → V5 正式 SCENE/DISPLAY_LAYER 与运行验收 → INTEGRATION。\n";
templates.optional.assets["asset-license-register.md"] += "\n效果图生成顺序固定为：建立全局基线 brief → 生成三张同条件候选效果图 → 同屏交给人工 → 人工选择确认一张 → 正式冻结全局 `visual_baseline` 与全部锚点 → 完成 foundation-only 的 SHARED 骨架和 MODULE 场景无关基础模块；随后进入各场景 V1，在 V1 内生成或接收并冻结 scene master/reference target、必需显示层宿主上下文图和初步还原草案，再进入 V2 拆解确认与生产方案、V3 正式资源验收、V4 页面草图保存与人工确认、V5 正式 SCENE/DISPLAY_LAYER 与运行验收。原子生成式位图资产以完整冻结效果图为主参考且额外继承全局锚点，在对应宿主场景阶段生产；系统按提示词、参考输入、材质、透明需求和可用能力选择生成器并记录实际工具/版本，未暴露时写 `not-provided`。全局基线人工选择是单独硬门，不能替代逐场景 V2 拆解确认，也不冒充 V2。`origin=provided` 只记录外部文件，`origin=generated` 才允许 generation_record。基线、锚点、target SHA 或实际 full prompt 变化会使旧一致性证据失效，并退回最早受影响阶段。\n";

/** 归一化旧模板片段，避免历史内置字符串继续生成被移除的旧 V2/V5 阶段。 */
function normalizeVisualStageTemplates(group) {
  for (const [key, value] of Object.entries(group)) {
    if (typeof value !== "string") continue;
    group[key] = value
      .replaceAll("V0→V1→V2→V3→V4→V5", "V0→V1→V2→V3→V4→V5")
      .replaceAll("V0→V5", "V0→V5")
      .replaceAll("V0-V5", "V0-V5")
      .replaceAll("V1→V5", "V1→V5")
      .replaceAll("走V3至V5", "走V2至V5")
      .replaceAll("V2b/V3/V5", "V2/V3/V5")
      .replaceAll("V3/V5", "V3/V5")
      .replaceAll("V3、V5", "V3、V5")
      .replaceAll("V5 接入", "V5 接入")
      .replaceAll("V5 集成/清理", "V5 集成/清理")
      .replaceAll("integration_status（V5）", "integration_status（V5）")
      .replaceAll("所有 V5", "所有 V5")
      .replaceAll("V5 已", "V5 已")
      .replaceAll("V5 由玩法与美术协作", "V5 由玩法与美术协作")
      .replaceAll("适用 V2 与 V5 联合证据", "适用 V2 与 V5 联合证据")
      .replaceAll("适用 V2 以及所有 V5", "适用 V2 以及 V5")
      .replaceAll("V2 条件门：高保真方向验证/必要取舍确认", "V2 条件门：拆解确认与生产方案")
      .replaceAll("代表图/拆解图确认", "拆解图/技术 JSON")
      .replaceAll("拆解图确认", "拆解确认")
      .replaceAll("拆解图确认", "拆解确认")
      .replaceAll("视觉方向冻结", "拆解方案确认")
      .replaceAll("v2-production-planning-complete", "v2-production-planning-complete")
      .replaceAll("`visual_human_approval`", "`visual-decomposition-confirmation/1.0`")
      .replaceAll("--stage V5", "--stage V5")
      .replaceAll("V5", "V5");
  }
}

normalizeVisualStageTemplates(templates.core);
normalizeVisualStageTemplates(templates.optional.assets);

// 模板中的技术基线固定浏览器 3D 默认值，避免新项目继承过时的二维运行时假设。
